import { build } from "esbuild";
import { writeFile } from "node:fs/promises";
const result = await build({
  entryPoints: ["packages/network-fixtures/src/index.ts"],
  bundle: true,
  platform: "node",
  format: "esm",
  target: "node22",
  write: false,
  minify: false,
  legalComments: "none",
});
await writeFile(
  "packages/playwright-export/src/runtime.generated.ts",
  "// Generated by scripts/build-export-runtime.mjs.\nexport const recordedRuntime = " +
    JSON.stringify(result.outputFiles[0].text) +
    ";\n",
);
